// The SQL behind `bun run admin:recover` (docs/auth-and-security.md#flows, D31): a locked-out
// admin loses passkeys, recovery codes and sessions, open links are revoked, and a new activation
// link is issued, as one file so `wrangler d1 execute` applies it as one batch. Values are
// validated or generated by the caller; the email is checked against `emailPattern` because it
// is placed inside a SQL literal. Every statement re-resolves the target by email AND role, so a
// client (or an unknown email) is untouched even if the caller's own lookup were skipped.
import { emailPattern } from "./bootstrap-admin.ts";

export interface RecoverAdmin {
  email: string;
  tokenHash: string;
  expiresAt: number;
  now: number;
}

export const recoverActor = "cli:admin-recover";

const checked = (email: string) => {
  if (!emailPattern.test(email)) throw new Error("email is not safe to place in SQL");
  return email;
};
const adminId = (email: string) =>
  `(SELECT "id" FROM "user" WHERE "email" = '${email}' AND "role" = 'admin')`;

/** One row when `email` is an admin that can be recovered: `{id, banned}`; no row otherwise. */
export function adminLookupSql(email: string) {
  return `SELECT "id" AS id, "banned" AS banned FROM "user" WHERE "email" = '${checked(email)}' AND "role" = 'admin';`;
}

export function recoverAdminSql({ email, tokenHash, expiresAt, now }: RecoverAdmin) {
  if (!/^[0-9a-f]{64}$/.test(tokenHash)) throw new Error("tokenHash is not a SHA-256 hex digest");
  if (!Number.isSafeInteger(expiresAt) || !Number.isSafeInteger(now)) {
    throw new Error("timestamps must be integers");
  }
  const target = adminId(checked(email));
  return `
INSERT INTO audit_log ("id", "at", "actor_id", "action", "target_user_id", "before_json", "after_json")
SELECT '${crypto.randomUUID()}', ${now}, '${recoverActor}', 'admin.recover', ${target},
  json_object('passkeys', (SELECT COUNT(*) FROM "passkey" WHERE "userId" = ${target}),
    'unusedCodes', (SELECT COUNT(*) FROM recovery_codes WHERE user_id = ${target} AND used_at IS NULL),
    'sessions', (SELECT COUNT(*) FROM "session" WHERE "userId" = ${target})),
  json_object('passkeys', 0, 'unusedCodes', 0, 'sessions', 0, 'linkOpen', json('true'))
WHERE ${target} IS NOT NULL;
UPDATE invitations SET revoked_at = ${now}
WHERE user_id = ${target} AND used_at IS NULL AND revoked_at IS NULL;
DELETE FROM "passkey" WHERE "userId" = ${target};
DELETE FROM "session" WHERE "userId" = ${target};
DELETE FROM recovery_codes WHERE user_id = ${target};
INSERT INTO invitations ("id", "user_id", "token_hash", "expires_at", "created_by")
SELECT '${crypto.randomUUID()}', ${target}, '${tokenHash}', ${expiresAt}, '${recoverActor}'
WHERE ${target} IS NOT NULL;
`;
}
